"""Legacy-compatible validation for OPP_MASTER opportunity records."""

from decimal import Decimal
from typing import Any


def _value(record: dict[str, Any] | None, field: str) -> Any:
    if record is None:
        return ""
    return record.get(field, "")


def _nvl(value: Any, default: Any) -> Any:
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    value = _nvl(value, 0)
    return Decimal(str(value))


def _date_gte(left: Any, right: Any) -> bool:
    left_text = "" if left is None else str(left)
    right_text = "" if right is None else str(right)

    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate all applicable legacy rules in rule-file order."""
    errors: list[dict] = []
    prior = old if event == "UPDATE" and old is not None else {}

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    # OPP-001
    if event in ("INSERT", "UPDATE"):
        if not (_number(_value(record, "AMT")) >= Decimal("0")):
            fail("E3001", "Amount negative")

    # OPP-002
    if event in ("INSERT", "UPDATE"):
        passes = not (
            _value(record, "STAT_CD") == "W"
            and _number(_value(record, "AMT")) == Decimal("0")
        )
        if not passes:
            fail("E3002", "Won opportunity requires amount")

    # OPP-003
    if event in ("INSERT", "UPDATE"):
        passes = not (
            _value(record, "STAT_CD") == "L"
            and _value(record, "LOST_RSN") == ""
        )
        if not passes:
            fail("E3003", "Lost reason required")

    # OPP-004
    if event in ("INSERT", "UPDATE"):
        passes = not (
            _value(record, "STAT_CD") == "W"
            and _value(record, "CLOSE_DT") == "00000000"
        )
        if not passes:
            fail("E3004", "Won opportunity requires close date")

    # OPP-005
    if event == "UPDATE":
        passes = not (
            _value(prior, "STAT_CD") == "W"
            and _value(record, "STAT_CD") != "W"
        )
        if not passes:
            fail("E3005", "Cannot reopen a won opportunity")

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        status = _value(record, "STAT_CD")
        stage_percent = _number(_value(record, "STAGE_PCT"))
        passes = (
            (status == "P" and stage_percent == Decimal("10"))
            or (status == "Q" and stage_percent == Decimal("25"))
            or (status == "N" and stage_percent == Decimal("60"))
            or (status == "W" and stage_percent == Decimal("100"))
            or (status == "L" and stage_percent == Decimal("0"))
        )
        if not passes:
            fail("E3006", "Stage percent inconsistent with status")

    # OPP-007
    if event == "INSERT":
        close_date = _value(record, "CLOSE_DT")
        passes = (
            close_date == "00000000"
            or _date_gte(close_date, today)
        )
        if not passes:
            fail("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether at least one validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
